Here is the root cause:
The bug is caused by insufficient validation of `num_aces` in `smb_inherit_dacl()`. The function trusts the on-disk `num_aces` value from the parent directory's DACL xattr without checking that it is consistent with the actual DACL payload size (`pdacl_size`). This allows an attacker to set a large `num_aces` (e.g., 65535) with minimal ACE data, triggering an oversized heap allocation and potential integer overflow in the size calculation. Additionally, the loop that walks the ACEs uses a weak minimum size check (`offsetof(struct smb_ace, access_req)`) instead of the actual minimum on-wire ACE size, and does not reject ACEs with a declared size below that minimum, allowing further out-of-bounds reads.

Here is the patch:

 int smb_inherit_dacl(struct ksmbd_conn *conn,
 		     const struct path *path,
 		     unsigned int uid, unsigned int gid)
 {
 	const struct smb_sid *psid, *creator = NULL;
 	struct smb_ace *parent_aces, *aces;
 	struct smb_acl *parent_pdacl;
 	struct smb_ntsd *parent_pntsd = NULL;
 	struct smb_sid owner_sid, group_sid;
 	struct dentry *parent = path->dentry->d_parent;
 	struct mnt_idmap *idmap = mnt_idmap(path->mnt);
 	int inherited_flags = 0, flags = 0, i, nt_size = 0, pdacl_size;
 	int rc = 0, pntsd_type, pntsd_size, acl_len, aces_size;
 	unsigned int dacloffset;
 	size_t dacl_struct_end;
 	u16 num_aces, ace_cnt = 0;
 	char *aces_base;
 	bool is_dir = S_ISDIR(d_inode(path->dentry)->i_mode);

 	pntsd_size = ksmbd_vfs_get_sd_xattr(conn, idmap,
 					    parent, &parent_pntsd);
 	if (pntsd_size <= 0)
 		return -ENOENT;

 	dacloffset = le32_to_cpu(parent_pntsd->dacloffset);
 	if (!dacloffset ||
 	    check_add_overflow(dacloffset, sizeof(struct smb_acl), &dacl_struct_end) ||
 	    dacl_struct_end > (size_t)pntsd_size) {
 		rc = -EINVAL;
 		goto free_parent_pntsd;
 	}

 	parent_pdacl = (struct smb_acl *)((char *)parent_pntsd + dacloffset);
 	acl_len = pntsd_size - dacloffset;
 	num_aces = le16_to_cpu(parent_pdacl->num_aces);
 	pntsd_type = le16_to_cpu(parent_pntsd->type);
 	pdacl_size = le16_to_cpu(parent_pdacl->size);

 	if (pdacl_size > acl_len || pdacl_size < sizeof(struct smb_acl)) {
 		rc = -EINVAL;
 		goto free_parent_pntsd;
 	}

-	aces_base = kmalloc(sizeof(struct smb_ace) * num_aces * 2,
-			    KSMBD_DEFAULT_GFP);
+	aces_size = pdacl_size - sizeof(struct smb_acl);
+
+	/*
+	 * Validate num_aces against the DACL payload before allocating.
+	 * Each ACE must be at least as large as its fixed-size header
+	 * (up to the SID base), so num_aces cannot exceed the payload
+	 * divided by the minimum ACE size.  This mirrors the existing
+	 * check in parse_dacl().
+	 */
+	if (num_aces > aces_size / (offsetof(struct smb_ace, sid) +
+				    offsetof(struct smb_sid, sub_auth) +
+				    sizeof(__le16))) {
+		rc = -EINVAL;
+		goto free_parent_pntsd;
+	}
+
+	aces_base = kmalloc_array(num_aces * 2, sizeof(struct smb_ace),
+				  KSMBD_DEFAULT_GFP);
 	if (!aces_base) {
 		rc = -ENOMEM;
 		goto free_parent_pntsd;
 	}

 	aces = (struct smb_ace *)aces_base;
 	parent_aces = (struct smb_ace *)((char *)parent_pdacl +
 			sizeof(struct smb_acl));
-	aces_size = acl_len - sizeof(struct smb_acl);

 	if (pntsd_type & DACL_AUTO_INHERITED)
 		inherited_flags = INHERITED_ACE;

 	for (i = 0; i < num_aces; i++) {
 		int pace_size;

-		if (offsetof(struct smb_ace, access_req) > aces_size)
+		if (aces_size < offsetof(struct smb_ace, sid) +
+		    CIFS_SID_BASE_SIZE)
 			break;

 		pace_size = le16_to_cpu(parent_aces->size);
-		if (pace_size > aces_size)
+		if (pace_size > aces_size ||
+		    pace_size < offsetof(struct smb_ace, sid) +
+				CIFS_SID_BASE_SIZE)
 			break;

 		aces_size -= pace_size;

 		flags = parent_aces->flags;
 		if (!smb_inherit_flags(flags, is_dir))
 			goto pass;
 		if (is_dir) {
 			flags &= ~(INHERIT_ONLY_ACE | INHERITED_ACE);
 			if (!(flags & CONTAINER_INHERIT_ACE))
 				flags |= INHERIT_ONLY_ACE;
 			if (flags & NO_PROPAGATE_INHERIT_ACE)
 				flags = 0;
 		} else {
 			flags = 0;
 		}

 		if (!compare_sids(&creator_owner, &parent_aces->sid)) {
 			creator = &creator_owner;
 			id_to_sid(uid, SIDOWNER, &owner_sid);
 			psid = &owner_sid;
 		} else if (!compare_sids(&creator_group, &parent_aces->sid)) {
 			creator = &creator_group;
 			id_to_sid(gid, SIDUNIX_GROUP, &group_sid);
 			psid = &group_sid;
 		} else {
 			creator = NULL;
 			psid = &parent_aces->sid;
 		}

 		if (is_dir && creator && flags & CONTAINER_INHERIT_ACE) {
 			smb_set_ace(aces, psid, parent_aces->type, inherited_flags,
 				    parent_aces->access_req);
 			nt_size += le16_to_cpu(aces->size);
 			ace_cnt++;
 			aces = (struct smb_ace *)((char *)aces + le16_to_cpu(aces->size));
 			flags |= INHERIT_ONLY_ACE;
 			psid = creator;
 		} else if (is_dir && !(parent_aces->flags & NO_PROPAGATE_INHERIT_ACE)) {
 			psid = &parent_aces->sid;
 		}

 		smb_set_ace(aces, psid, parent_aces->type, flags | inherited_flags,
 			    parent_aces->access_req);
 		nt_size += le16_to_cpu(aces->size);
 		aces = (struct smb_ace *)((char *)aces + le16_to_cpu(aces->size));
 		ace_cnt++;
 pass:
 		parent_aces = (struct smb_ace *)((char *)parent_aces + pace_size);
 	}

 	if (nt_size > 0) {
 		struct smb_ntsd *pntsd;
 		struct smb_acl *pdacl;
 		struct smb_sid *powner_sid = NULL, *pgroup_sid = NULL;
 		int powner_sid_size = 0, pgroup_sid_size = 0, pntsd_size;
 		int pntsd_alloc_size;

 		if (parent_pntsd->osidoffset) {
 			powner_sid = (struct smb_sid *)((char *)parent_pntsd +
 					le32_to_cpu(parent_pntsd->osidoffset));
 			powner_sid_size = 1 + 1 + 6 + (powner_sid->num_subauth * 4);
 		}
 		if (parent_pntsd->gsidoffset) {
 			pgroup_sid = (struct smb_sid *)((char *)parent_pntsd +
 					le32_to_cpu(parent_pntsd->gsidoffset));
 			pgroup_sid_size = 1 + 1 + 6 + (pgroup_sid->num_subauth * 4);
 		}

 		pntsd_alloc_size = sizeof(struct smb_ntsd) + powner_sid_size +
 			pgroup_sid_size + sizeof(struct smb_acl) + nt_size;

 		pntsd = kzalloc(pntsd_alloc_size, KSMBD_DEFAULT_GFP);
 		if (!pntsd) {
 			rc = -ENOMEM;
 			goto free_aces_base;
 		}

 		pntsd->revision = cpu_to_le16(1);
 		pntsd->type = cpu_to_le16(SELF_RELATIVE | DACL_PRESENT);
 		if (le16_to_cpu(parent_pntsd->type) & DACL_AUTO_INHERITED)
 			pntsd->type |= cpu_to_le16(DACL_AUTO_INHERITED);
 		pntsd_size = sizeof(struct smb_ntsd);
 		pntsd->osidoffset = parent_pntsd->osidoffset;
 		pntsd->gsidoffset = parent_pntsd->gsidoffset;
 		pntsd->dacloffset = parent_pntsd->dacloffset;

 		if ((u64)le32_to_cpu(pntsd->osidoffset) + powner_sid_size >
 		    pntsd_alloc_size) {
 			rc = -EINVAL;
 			kfree(pntsd);
 			goto free_aces_base;
 		}

 		if ((u64)le32_to_cpu(pntsd->gsidoffset) + pgroup_sid_size >
 		    pntsd_alloc_size) {
 			rc = -EINVAL;
 			kfree(pntsd);
 			goto free_aces_base;
 		}

 		if ((u64)le32_to_cpu(pntsd->dacloffset) + sizeof(struct smb_acl) + nt_size >
 		    pntsd_alloc_size) {
 			rc = -EINVAL;
 			kfree(pntsd);
 			goto free_aces_base;
 		}

 		if (pntsd->osidoffset) {
 			struct smb_sid *owner_sid = (struct smb_sid *)((char *)pntsd +
 					le32_to_cpu(pntsd->osidoffset));
 			memcpy(owner_sid, powner_sid, powner_sid_size);
 			pntsd_size += powner_sid_size;
 		}

 		if (pntsd->gsidoffset) {
 			struct smb_sid *group_sid = (struct smb_sid *)((char *)pntsd +
 					le32_to_cpu(pntsd->gsidoffset));
 			memcpy(group_sid, pgroup_sid, pgroup_sid_size);
 			pntsd_size += pgroup_sid_size;
 		}

 		if (pntsd->dacloffset) {
 			struct smb_ace *pace;

 			pdacl = (struct smb_acl *)((char *)pntsd + le32_to_cpu(pntsd->dacloffset));
 			pdacl->revision = cpu_to_le16(2);
 			pdacl->size = cpu_to_le16(sizeof(struct smb_acl) + nt_size);
 			pdacl->num_aces = cpu_to_le16(ace_cnt);
 			pace = (struct smb_ace *)((char *)pdacl + sizeof(struct smb_acl));
 			memcpy(pace, aces_base, nt_size);
 			pntsd_size += sizeof(struct smb_acl) + nt_size;
 		}

 		ksmbd_vfs_set_sd_xattr(conn, idmap, path, pntsd, pntsd_size, false);
 		kfree(pntsd);
 	}

 free_aces_base:
 	kfree(aces_base);
 free_parent_pntsd:
 	kfree(parent_pntsd);
 	return rc;
 }



